def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    x = []
    for v in history:
        try:
            z = float(v)
            if math.isfinite(z):
                x.append(z)
        except (TypeError, ValueError):
            pass
    if horizon <= 0:
        return []
    if not x:
        return [0.0] * horizon
    n = len(x)
    if n < 16:
        return [float(statistics.median(x[-min(7, n):]))] * horizon

    def smape(a, b):
        return 200.0 * abs(a - b) / (abs(a) + abs(b) + 1e-9)

    max_p = min(90, (n - 8) // 2)
    candidates = []
    if max_p >= 2:
        for p in range(2, max_p + 1):
            start = max(p + 2, n - min(76, n - p - 1))
            errs = []
            base_errs = []
            for i in range(start, n):
                lo = max(p, i - 4 * p)
                ds = [x[j] - x[j - p] for j in range(lo, i)]
                d = statistics.median(ds) if ds else 0.0
                pred = x[i - p] + d
                base = statistics.median(x[max(0, i - 9):i])
                errs.append(smape(x[i], pred))
                base_errs.append(smape(x[i], base))
            if len(errs) >= 8:
                score = sum(errs) / len(errs) + 0.015 * p
                base_score = sum(base_errs) / len(base_errs)
                candidates.append((score, base_score, p))

    if candidates:
        score, base_score, p = min(candidates)
    else:
        score, base_score, p = float('inf'), 0.0, 1

    if score < 0.90 * base_score:
        buf = list(x)
        for _ in range(horizon):
            lo = max(p, len(buf) - 4 * p)
            ds = [buf[j] - buf[j - p] for j in range(lo, len(buf))]
            d = statistics.median(ds) if ds else 0.0
            y = buf[-p] + d
            if not math.isfinite(y):
                y = buf[-1]
            buf.append(float(y))
        return buf[-horizon:]

    w = x[-min(15, n):]
    slopes = []
    for i in range(len(w)):
        for j in range(i + 1, len(w)):
            slopes.append((w[j] - w[i]) / (j - i))
    slope = statistics.median(slopes) if slopes else 0.0
    steps = [abs(w[i] - w[i - 1]) for i in range(1, len(w))]
    scale = statistics.median(steps) if steps else 0.0
    if scale > 0:
        slope = max(-3.0 * scale, min(3.0 * scale, slope))
    level = statistics.median(w[-min(5, len(w)):])
    return [float(level + slope * (k + 1)) for k in range(horizon)]

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    x = []
    for v in history:
        try:
            z = float(v)
            if math.isfinite(z):
                x.append(z)
        except (TypeError, ValueError):
            pass
    if horizon <= 0:
        return []
    if not x:
        return [0.0] * horizon
    n = len(x)
    if n < 18:
        return [float(statistics.median(x[-min(7, n):]))] * horizon

    def smape(a, b):
        return 200.0 * abs(a - b) / (abs(a) + abs(b) + 1e-9)

    max_p = min(90, (n - 6) // 3)
    ranked = []
    for p in range(2, max_p + 1):
        start = max(2 * p, n - min(76, n - 2 * p))
        errs = []
        base_errs = []
        for i in range(start, n):
            diffs = []
            j = i - p
            while j - p >= 0 and len(diffs) < 4:
                diffs.append(x[j] - x[j - p])
                j -= p
            inc = statistics.median(diffs) if diffs else 0.0
            pred = x[i - p] + inc
            base = statistics.median(x[max(0, i - 9):i])
            errs.append(smape(x[i], pred))
            base_errs.append(smape(x[i], base))
        if len(errs) >= 8:
            ranked.append((sum(errs) / len(errs) + 0.01 * p,
                           sum(base_errs) / len(base_errs), p))

    if not ranked:
        return [float(statistics.median(x[-7:]))] * horizon
    score, base_score, p = min(ranked)
    if score >= 0.88 * base_score:
        level = statistics.median(x[-min(9, n):])
        return [float(level)] * horizon

    phase_inc = {}
    recent_cut = max(p, n - 6 * p)
    for phase in range(p):
        ds = []
        for j in range(recent_cut, n):
            if j % p == phase and j - p >= 0:
                ds.append(x[j] - x[j - p])
        phase_inc[phase] = statistics.median(ds[-5:]) if ds else 0.0

    all_inc = list(phase_inc.values())
    center = statistics.median(all_inc) if all_inc else 0.0
    deviations = [abs(v - center) for v in all_inc]
    spread = statistics.median(deviations) if deviations else 0.0
    if spread > 0:
        lo = center - 4.0 * spread
        hi = center + 4.0 * spread
        phase_inc = {q: max(lo, min(hi, v)) for q, v in phase_inc.items()}

    buf = list(x)
    for _ in range(horizon):
        idx = len(buf)
        inc = phase_inc.get(idx % p, center)
        y = buf[-p] + inc
        if not math.isfinite(y):
            y = buf[-1]
        buf.append(float(y))
    return buf[-horizon:]
